export const getActiveTimeline = (timelineId?: string): TimelineConfig => {
  if (timelineId && TIMELINES_CONFIG[timelineId]) {
    return TIMELINES_CONFIG[timelineId];
  }
  return TIMELINES_CONFIG["timeline_thanh_van"];
};

export const getActiveWorldGraph = (timelineId?: string): Record<string, LocationNode> => {
  const tl = getActiveTimeline(timelineId);
  return { ...FIXED_WORLD_GRAPH, ...(tl.worldGraph || {}) };
};

export const DEFAULT_CANON_TIMELINE: CanonEvent[] = TIMELINES_CONFIG["timeline_thanh_van"].canonEvents;

