const parseAIStat = (val) => {
  if (val === undefined || val === null) return 0;
  if (typeof val === 'number') {
      if (isNaN(val) || !isFinite(val)) return 0;
      return Math.min(1e15, Math.max(-1e15, val)); // V12.04 FIX: Tăng giới hạn lên 1 Triệu Tỷ (1e15)
  }
  const strVal = String(val).replace(/[^0-9.-]+/g, ''); 
  const parsed = parseFloat(strVal);
  if (isNaN(parsed) || !isFinite(parsed)) return 0;
  return Math.min(1e15, Math.max(-1e15, parsed)); // V12.04 FIX
};

const formatLocationDisplay = (loc, universe, timelineId) => {
    if (!loc) return '';
    const activeGraph = getActiveWorldGraph(timelineId);
    const node = activeGraph[loc] || Object.values(activeGraph).find(n => n.name === loc);
    if (node) {
        const reg = (node.regionName || node.region || '').trim();
        return (reg && reg !== 'undefined' && reg !== 'null') ? `${node.name} (${reg})` : node.name;
    }
    return String(loc).replace(/\s*\((?:undefined|null)\)/gi, '').trim();
};

const formatLargeNumber = (num) => {
  if (num === undefined || num === null || isNaN(num) || !isFinite(num)) return '0';
  const absNum = Math.abs(num);
  if (absNum < 1000) return Math.floor(num).toLocaleString('vi-VN');

  let formatted = '';
  if (absNum >= 1e18) {
    const tyTy = (absNum / 1e18).toFixed(2);
    formatted = `${tyTy} Tỷ Tỷ`;
  } else if (absNum >= 1e15) {
    const trTy = (absNum / 1e15).toFixed(2);
    formatted = `${trTy} Triệu Tỷ`;
  } else if (absNum >= 1e12) {
    const nghinTy = (absNum / 1e12).toFixed(2);
    formatted = `${nghinTy} Nghìn Tỷ`;
  } else if (absNum >= 1e9) {
    const ty = Math.floor(absNum / 1e9);
    const tr = Math.floor((absNum % 1e9) / 1e8);
    formatted = tr > 0 ? `${ty}Tỷ ${tr}` : `${ty}Tỷ`;
  } else if (absNum >= 1e6) {
    const tr = Math.floor(absNum / 1e6);
    const k = Math.floor((absNum % 1e6) / 1e5);
    formatted = k > 0 ? `${tr}Tr ${k}` : `${tr}Tr`;
  } else if (absNum >= 1e3) {
    const k = Math.floor(absNum / 1e3);
    const h = Math.floor((absNum % 1e3) / 1e2);
    formatted = h > 0 ? `${k}N ${h}` : `${k}N`;
  }
  return num < 0 ? `-${formatted}` : formatted;
};

// V4.2: Hàm định dạng thời gian cho Hiệu ứng trạng thái
const formatEffTime = (m) => {
    if (!m || m <= 0) return "0 phút";
    if (m > 50000000) return "Vĩnh viễn"; // V9.84: Nhận diện thời gian vô hạn của Tâm Pháp
    if (m < 60) return `${Math.floor(m)} phút`;
    if (m < 1440) return `${Math.floor(m/60)} giờ`;
    if (m < 43200) return `${Math.floor(m/1440)} ngày`;
    if (m < 518400) return `${Math.floor(m/43200)} tháng`;
    return `${Math.floor(m/518400)} năm`;
};

// V6.32: Hàm lấy Mốc Thời Gian Thực cho Bảng Cần Mẫn (Chương)
const getCurrentWeekStr = () => {
    const d = new Date();
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay()||7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(),0,1));
    const weekNo = Math.ceil(( ( (d - yearStart) / 86400000) + 1)/7);
    return `${d.getUTCFullYear()}-W${weekNo}`;
};
const getCurrentMonthStr = () => {
    const d = new Date();
    return `${d.getFullYear()}-${(d.getMonth()+1).toString().padStart(2, '0')}`;
};
const safeDecompress = (str) => {
    if (!str) return null;
    if (typeof str === 'object') return str;
    if (typeof str === 'string' && str.trim().startsWith('{')) {
        try { return JSON.parse(str.trim()); } catch(e) {}
    }
    try {
        const decodedBase64 = LZString.decompressFromBase64(str);
        if (decodedBase64) return JSON.parse(decodedBase64);
    } catch(e) {}
    try {
        const decodedURI = LZString.decompressFromEncodedURIComponent(str);
        if (decodedURI) return JSON.parse(decodedURI);
    } catch(e) {}
    try {
        const decodedUTF16 = LZString.decompressFromUTF16(str);
        if (decodedUTF16) return JSON.parse(decodedUTF16);
    } catch(e) {}
    return null;
};

const safeDecompressLogs = (str) => {
    if (!str) return [];
    try {
        const decodedBase64 = LZString.decompressFromBase64(str);
        if (decodedBase64) return JSON.parse(decodedBase64);
    } catch(e) {}
    try {
        const decodedURI = LZString.decompressFromEncodedURIComponent(str);
        if (decodedURI) return JSON.parse(decodedURI);
    } catch(e) {}
    try {
        const decodedUTF16 = LZString.decompressFromUTF16(str);
        if (decodedUTF16) return JSON.parse(decodedUTF16);
    } catch(e) {}
    return [];
};

// V1.24.1: Tự động sửa lỗi Hài Cốt / Xác Chết chiếm đoạt danh phận Đạo Lữ của Althea hoặc NPC khác
const sanitizeNpcRelationships = (npcs: any[], playerGender: string = 'Nam') => {
    if (!Array.isArray(npcs) || npcs.length === 0) return;
    const isCorpseOrSkeleton = (nameStr: string) => /(hài cốt|xác chết|bộ xương|di cốt|tàn cốt|thi thể|vô danh cổ tu|vô danh|cổ tu)/i.test(nameStr || '');
    const isSpouseRelation = (relStr: string) => /(thê tử|phu quân|đạo lữ|hồng nhan|tỳ thiếp|người tình|thê thiếp|vợ|chồng|ái nhân|bạn đời)/i.test(relStr || '');

    // 1. Dọn dẹp lỗi chuỗi danh phận, giới tính danh phận
    npcs.forEach((npc: any) => {
        if (npc.name) {
            npc.name = String(npc.name).replace(/(?:\s*\(\s*ĐÃ CHẾT\s*\))+/ig, '').trim();
        }
        if (npc.relationType) {
            npc.relationType = String(npc.relationType).replace(/(?:\s*\((?:Phàm nhân|Chính đạo|Ma đạo|Trung lập|Không rõ|Thuộc hạ|Trung thành tuyệt đối|Tà tu|Tán tu|Yêu tộc|Ma tộc)\))+\s*$/ig, '').trim();
            if (/(thê tử|vợ)/i.test(npc.relationType) && playerGender === 'Nữ') npc.relationType = 'Phu quân';
            else if (/(phu quân|chồng)/i.test(npc.relationType) && playerGender === 'Nam') npc.relationType = 'Thê tử';
            if (npc.gender === 'Nữ' && String(npc.relationType).toLowerCase() === 'phu quân') npc.relationType = 'Thê tử';
            if (npc.gender === 'Nam' && String(npc.relationType).toLowerCase() === 'thê tử') npc.relationType = 'Phu quân';
            if (playerGender === 'Nam' && String(npc.name).includes('Vọng Thư') && String(npc.relationType).toLowerCase() === 'phu quân') {
                npc.relationType = 'Thê tử';
                if (!npc.gender) npc.gender = 'Nữ';
            }
        }
        if (npc.role) {
            npc.role = String(npc.role).replace(/(?:\s*\((?:Phàm nhân|Chính đạo|Ma đạo|Trung lập|Không rõ|Thuộc hạ|Trung thành tuyệt đối|Tà tu|Tán tu|Yêu tộc|Ma tộc)\))+\s*$/ig, '').trim();
        }
    });

    // 2. Xử lý triệt để Hài cốt / Xác chết / Vô Danh Cổ Tu bị gán nhầm danh phận Đạo Lữ (Điển hình: Vô Danh Cổ Tu cướp danh phận của Althea)
    npcs.forEach((npc: any) => {
        if (npc.isDead || isCorpseOrSkeleton(npc.name)) {
            if (isSpouseRelation(npc.relationType)) {
                const summaryText = (String(npc.historySummary || '') + ' ' + String(npc.state || '')).toLowerCase();
                
                let rightfulPartner = npcs.find((other: any) => 
                    !other.isDead && !isCorpseOrSkeleton(other.name) && 
                    (summaryText.includes(String(other.name || '').toLowerCase()) || 
                     (other.aliases || []).some((al: string) => summaryText.includes(String(al).toLowerCase())) ||
                     (String(other.name || '').toLowerCase().includes('althea') && (summaryText.includes('song tu') || summaryText.includes('truyền lực')))
                    )
                );

                if (!rightfulPartner && isCorpseOrSkeleton(npc.name)) {
                    rightfulPartner = npcs.find((other: any) => 
                        !other.isDead && String(other.name || '').toLowerCase().includes('althea')
                    );
                }

                if (rightfulPartner) {
                    rightfulPartner.relationType = npc.relationType || 'Đạo Lữ Đồng Hành';
                    if (!rightfulPartner.affinity || Number(rightfulPartner.affinity) < 80) rightfulPartner.affinity = 100;
                    if (summaryText.includes('song tu') || summaryText.includes('truyền lực')) {
                        rightfulPartner.historySummary = npc.historySummary;
                        rightfulPartner.state = npc.state;
                    }
                }

                npc.relationType = "Âm Dương Cách Biệt";
                npc.state = "Đã an táng / Hoàng Tuyền";
                if (summaryText.includes('song tu') || summaryText.includes('truyền lực')) {
                    npc.historySummary = "Hài cốt cổ tu tiền bối, đã được an táng chu đáo nơi nghĩa địa/rừng sâu.";
                }
            }
        }
    });
};

