const getNightmareStats = (levelString) => {
  const lv = String(levelString || '').toLowerCase().trim();
  if (!lv || lv.includes('phàm nhân') || lv.includes('người thường')) {
    return { atk: 100, def: 100, spd: 100, spp: 100, hp: 1000, mp: 1000, valueOf() { return this.atk; } };
  }

  let subKey = 'default';
  const tangM = lv.match(/tầng\s*(\d+)/);
  if (tangM) {
    const t = parseInt(tangM[1], 10);
    subKey = 't' + Math.max(1, Math.min(10, t));
  } else if (lv.includes('sơ kỳ')) subKey = 'so';
  else if (lv.includes('trung kỳ')) subKey = 'trung';
  else if (lv.includes('hậu kỳ')) subKey = 'hau';
  else if (lv.includes('viên mãn') || lv.includes('cực cảnh') || lv.includes('đỉnh phong')) subKey = 'vien';

  for (let i = NIGHTMARE_DATA.length - 1; i >= 0; i--) {
    const item = NIGHTMARE_DATA[i];
    if (item.regex.test(lv)) {
      const v4 = item.r4[subKey] || item.r4.default || 100;
      const v3 = item.r3[subKey] || item.r3.default || 1000;
      return {
        atk: v4, def: v4, spd: v4, spp: v4,
        hp: v3, mp: v3,
        valueOf() { return this.atk; }
      };
    }
  }

  return { atk: 100, def: 100, spd: 100, spp: 100, hp: 1000, mp: 1000, valueOf() { return this.atk; } };
};

const generateNPCStats = (levelName, npcData = {}) => {
    // V1.22.2: NPC CỐ ĐỊNH trong Vạn Linh Ký có chỉ số định sẵn, bảo toàn nguyên gốc, CẤM auto-scale ngẫu nhiên
    if (npcData && (npcData.id || npcData.vlkId)) {
        const checkId = npcData.vlkId || npcData.id;
        if (typeof VAN_LINH_KY !== 'undefined' && (VAN_LINH_KY as any)[checkId]) {
            const vlk = (VAN_LINH_KY as any)[checkId];
            let fixedHp = vlk.hp || 100;
            let fixedMp = vlk.mp || 0;
            let fixedAtk = vlk.atk || 10;
            let fixedDef = vlk.def || 10;
            let fixedSpd = vlk.spd || 10;
            let fixedSpp = vlk.spp || 10;
            if (npcData.isNightmare) {
                const nm = getNightmareStats(vlk.canh || levelName);
                fixedAtk = Math.max(fixedAtk, nm.atk);
                fixedDef = Math.max(fixedDef, nm.def);
                fixedSpd = Math.max(fixedSpd, nm.spd);
                fixedSpp = Math.max(fixedSpp, nm.spp);
                fixedHp = Math.max(fixedHp, nm.hp);
                fixedMp = Math.max(fixedMp, nm.mp);
            }
            return {
                maxHp: fixedHp, hp: fixedHp,
                maxMp: fixedMp, mp: fixedMp,
                attack: fixedAtk,
                defense: fixedDef,
                speed: fixedSpd,
                spiritPower: fixedSpp,
                equipped: { weapon: null, armor: null, head: null, boots: null, artifact: null, accessory: null },
                activeEffects: []
            };
        }
    }
    if (npcData && npcData.name && typeof VAN_LINH_KY !== 'undefined') {
        const cleanN = String(npcData.name).trim().toLowerCase();
        const found = Object.values(VAN_LINH_KY as Record<string, any>).find(v => v && (String(v.ten).toLowerCase() === cleanN || (v.bietDanh && String(v.bietDanh).toLowerCase() === cleanN)));
        if (found) {
            let fixedHp = found.hp || 100;
            let fixedMp = found.mp || 0;
            let fixedAtk = found.atk || 10;
            let fixedDef = found.def || 10;
            let fixedSpd = found.spd || 10;
            let fixedSpp = found.spp || 10;
            if (npcData.isNightmare) {
                const nm = getNightmareStats(found.canh || levelName);
                fixedAtk = Math.max(fixedAtk, nm.atk);
                fixedDef = Math.max(fixedDef, nm.def);
                fixedSpd = Math.max(fixedSpd, nm.spd);
                fixedSpp = Math.max(fixedSpp, nm.spp);
                fixedHp = Math.max(fixedHp, nm.hp);
                fixedMp = Math.max(fixedMp, nm.mp);
            }
            return {
                maxHp: fixedHp, hp: fixedHp,
                maxMp: fixedMp, mp: fixedMp,
                attack: fixedAtk,
                defense: fixedDef,
                speed: fixedSpd,
                spiritPower: fixedSpp,
                equipped: { weapon: null, armor: null, head: null, boots: null, artifact: null, accessory: null },
                activeEffects: []
            };
        }
    }
    let stageCfg = getStageConfig(levelName);
    // V1.39 THÀNH KHÔN: Khóa cứng cảnh giới Thần Sao C'tan tối thiểu Đạo Tổ (Stage 20)
    const _checkRaceRole = (String(npcData.race || '') + ' ' + String(npcData.role || '')).toLowerCase();
    if (/(thần sao|c'tan|ctan)/.test(_checkRaceRole) && stageCfg.id < 20) {
        stageCfg = getStageConfig('Đạo Tổ');
    }
    const mult = stageCfg.statMult;
    
    // Sửa lỗi: Cân bằng Cực Cảnh - Cho tăng tiến mượt mà từ đầu thay vì nhảy vọt ở Nguyên Anh
    let cucCanhMult = stageCfg.id; 
    
    // Tỷ lệ ngẫu nhiên dao động từ 85% đến 115% sức mạnh chuẩn
    const variance = () => 0.85 + Math.random() * 0.3; 
    
    // --- MA TRẬN HỆ SỐ ---
    let hpDefMult = 1.0;
    let atkSpdMult = 1.0;
    let globalMult = 1.0;

    const raceStr = String(npcData.race || 'Nhân Tộc').toLowerCase();
    const roleStr = String(npcData.role || '').toLowerCase();
    const alignStr = String(npcData.alignment || '').toLowerCase();
    
    // FIX LỖI OBJECT: Chuyển đổi mảng Khí vận thành mảng Chuỗi (String) để so sánh
    const traitsArr = Array.isArray(npcData.traits) ? npcData.traits : [];
    const traitNames = traitsArr.map(t => typeof t === 'object' ? (t.name || '') : String(t));

    // V1.39 THÀNH KHÔN: ĐỒNG BỘ TOÀN DIỆN 27 XUẤT THÂN & CHỦNG TỘC VÀO MA TRẬN CHỈ SỐ NPC
    if (/(cự long|viễn cổ cự long|farum azula)/i.test(raceStr) || /(cự long|viễn cổ cự long)/i.test(roleStr)) {
        hpDefMult = 2.5;
        atkSpdMult = 1.8;
        globalMult *= 1.5;
    } else if (/(thần sao|c'tan|ctan)/i.test(raceStr) || /(thần sao|c'tan|ctan)/i.test(roleStr)) {
        hpDefMult = 5.0;
        atkSpdMult = 3.0;
        globalMult *= 3.0;
    } else if (/(chân long|long tộc)/i.test(raceStr) || /(chân long|long tộc)/i.test(roleStr)) {
        hpDefMult = 2.2;
        atkSpdMult = 1.6;
        globalMult *= 1.4;
    } else if (/(côn bằng)/i.test(raceStr) || /(côn bằng)/i.test(roleStr)) {
        hpDefMult = 2.0;
        atkSpdMult = 2.2;
        globalMult *= 1.5;
    } else if (/(thanh khâu|hồ tộc)/i.test(raceStr) || /(thanh khâu|hồ tộc)/i.test(roleStr)) {
        hpDefMult = 0.9;
        atkSpdMult = 1.5;
        globalMult *= 1.3;
    } else if (/(thái thản|titan|vu tộc|thập nhị vu)/i.test(raceStr) || /(thái thản|titan|vu tộc)/i.test(roleStr)) {
        hpDefMult = 3.2;
        atkSpdMult = 1.3;
        globalMult *= 1.4;
    } else if (/(bỉ mông|behemoth)/i.test(raceStr) || /(bỉ mông|behemoth)/i.test(roleStr)) {
        hpDefMult = 2.8;
        atkSpdMult = 1.4;
        globalMult *= 1.3;
    } else if (/(thao thiết)/i.test(raceStr) || /(thao thiết)/i.test(roleStr)) {
        hpDefMult = 2.5;
        atkSpdMult = 1.5;
        globalMult *= 1.3;
    } else if (/(tiên tộc|tinh linh|elf)/i.test(raceStr) || /(tiên tộc|tinh linh|elf)/i.test(roleStr)) {
        hpDefMult = 0.9;
        atkSpdMult = 1.6;
        globalMult *= 1.2;
    } else if (/(dực tộc|thiên thần|angel)/i.test(raceStr) || /(dực tộc|thiên thần|angel)/i.test(roleStr)) {
        hpDefMult = 1.2;
        atkSpdMult = 1.8;
        globalMult *= 1.3;
    } else if (/(huyết tộc|vampire|blood angel)/i.test(raceStr) || /(huyết tộc|vampire|blood angel)/i.test(roleStr)) {
        hpDefMult = 1.4;
        atkSpdMult = 1.7;
        globalMult *= 1.3;
    } else if (/(mị ma|succubus|sắc nghiệt)/i.test(raceStr) || /(mị ma|succubus|sắc nghiệt)/i.test(roleStr)) {
        hpDefMult = 1.0;
        atkSpdMult = 1.6;
        globalMult *= 1.3;
    } else if (/(ác mộng|gian kỳ|nightmare)/i.test(raceStr) || /(ác mộng|gian kỳ|nightmare)/i.test(roleStr)) {
        hpDefMult = 0.9;
        atkSpdMult = 1.9;
        globalMult *= 1.3;
    } else if (/(thi tộc|vong linh|undead)/i.test(raceStr) || /(thi tộc|vong linh|undead)/i.test(roleStr)) {
        hpDefMult = 2.0;
        atkSpdMult = 1.1;
        globalMult *= 1.2;
    } else if (/(cơ khí|cyborg|mechanicus|contingency)/i.test(raceStr) || /(cơ khí|cyborg|mechanicus)/i.test(roleStr)) {
        hpDefMult = 2.2;
        atkSpdMult = 1.6;
        globalMult *= 1.4;
    } else if (/(goblin|green tide)/i.test(raceStr) || /(goblin|green tide)/i.test(roleStr)) {
        hpDefMult = 0.8;
        atkSpdMult = 1.2;
        globalMult *= 0.9;
    } else if (/(yêu|ma|vu|thú|hung|cự nhân)/.test(raceStr)) {
        hpDefMult = 1.5;
    } else if (/(nhân|tiên|thần)/.test(raceStr)) {
        hpDefMult = 0.8;
        atkSpdMult = 1.3;
    }

    // 2. Xuất Thân / Lai Lịch (Background)
    if (/(tông|thánh địa|gia tộc|hoàng|đế|cung|điện|các)/.test(roleStr) || /(tông|thánh địa|gia tộc|hoàng|đế|cung|điện|các)/.test(alignStr)) {
        globalMult *= 1.4; // Giàu có, đồ xịn
    } else if (/(tán tu|nô lệ|khất cái|ăn mày|tạp dịch|thường dân)/.test(roleStr)) {
        globalMult *= 0.8; // Nghèo khổ
    }

    // 3. Khí Vận (Traits)
    if (traitNames.includes('Thiên Mệnh Chi Tử') || traitNames.includes('Khí Vận Chi Tử') || traitNames.includes('Khí Vận Chi Nữ') || traitNames.includes('Thiên Mệnh Ma Tôn') || traitNames.includes('Thiên Chùy Bách Luyện') || traitNames.includes('Đại Khí Vận') || traitNames.includes('Thiên Mệnh Hồng Nhan')) {
        globalMult *= 2.0; // Con cưng thiên đạo x2
    }
    if (traitNames.includes('Thiên Sát Cô Tinh') || traitNames.includes('Ách Vận Bám Thân') || traitNames.includes('Thiên Sinh Phế Vật')) {
        globalMult *= 0.6; // Xui xẻo, phế vật
    }

    const finalHpDefMult = cucCanhMult * hpDefMult * globalMult;
    const finalAtkSpdMult = cucCanhMult * atkSpdMult * globalMult;
    
    // Công thức HP Hàm Mũ kết hợp Hệ số (HP/MP là chỉ số Tổng nên vẫn giữ mult)
    const expectedMaxHp = Math.floor(100 * mult * finalHpDefMult * Math.pow(1.15, stageCfg.id - 1) * variance());
    const expectedMaxMp = Math.floor(50 * mult * cucCanhMult * globalMult * Math.pow(1.15, stageCfg.id - 1) * variance());
    
    // V2.24 ĐẠI TU: CHỈ SỐ THỂ PHÁCH NPC THEO ĐÚNG CẢNH GIỚI (BÁO LỖI DARK)
    // Hệ số đột phá x2.5 lũy tiến theo từng đại cảnh giới, tiệm cận ngưỡng trần HardCap của cảnh giới đó
    const stageHardCap = 2625 * Math.pow(stageCfg.id, 3);
    const growthExp = Math.floor(10 * Math.pow(2.5, stageCfg.id - 1));
    const stageBaseStat = Math.min(Math.floor(stageHardCap * 0.75), growthExp);
    
    // Bóc tách tiểu cảnh giới (Sơ kỳ x1.0, Trung kỳ x1.25, Hậu kỳ x1.5, Viên Mãn / Đỉnh Phong x1.8)
    let minorMult = 1.0;
    const lvlStr = String(npcData.level || levelName || '').toLowerCase();
    if (lvlStr.includes('trung kỳ') || lvlStr.includes('giai đoạn 2')) minorMult = 1.25;
    else if (lvlStr.includes('hậu kỳ') || lvlStr.includes('giai đoạn 3')) minorMult = 1.5;
    else if (lvlStr.includes('viên mãn') || lvlStr.includes('đỉnh phong') || lvlStr.includes('cực hạn')) minorMult = 1.8;
    else {
        const tangMatch = lvlStr.match(/tầng\s+(\d+)/);
        if (tangMatch) {
            const tang = parseInt(tangMatch[1]);
            minorMult = 1.0 + Math.min(0.8, Math.max(0, (tang - 1) * 0.1));
        }
    }
    
    const realmBaseline = Math.floor(stageBaseStat * minorMult);
    const baseAtk = Math.max(10, Math.floor(realmBaseline * atkSpdMult * globalMult * variance()));
    const baseDef = Math.max(10, Math.floor(realmBaseline * hpDefMult * globalMult * variance()));
    const baseSpd = Math.max(10, Math.floor(realmBaseline * atkSpdMult * globalMult * variance()));
    const baseSpp = Math.max(10, Math.floor(realmBaseline * globalMult * variance()));

    let finalAtk = baseAtk, finalDef = baseDef, finalSpd = baseSpd, finalSpp = baseSpp;
    let expectedFinalHp = expectedMaxHp, expectedFinalMp = expectedMaxMp;
    if (npcData.isNightmare) {
        const nm = getNightmareStats(levelName);
        finalAtk = Math.max(finalAtk, nm.atk);
        finalDef = Math.max(finalDef, nm.def);
        finalSpd = Math.max(finalSpd, nm.spd);
        finalSpp = Math.max(finalSpp, nm.spp);
        expectedFinalHp = Math.max(expectedFinalHp, nm.hp);
        expectedFinalMp = Math.max(expectedFinalMp, nm.mp);
    }

    const baseStats = npcData.baseStats;

    if (baseStats) {
        return {
            maxHp: Math.max(baseStats.maxHp || 100, expectedFinalHp),
            hp: Math.max(baseStats.maxHp || 100, expectedFinalHp), // Hồi full máu khi lên cấp
            maxMp: Math.max(baseStats.maxMp || 50, expectedFinalMp),
            mp: Math.max(baseStats.maxMp || 50, expectedFinalMp),
            attack: Math.max(baseStats.attack || 10, finalAtk),
            defense: Math.max(baseStats.defense || 10, finalDef),
            speed: Math.max(baseStats.speed || 10, finalSpd),
            spiritPower: Math.max(baseStats.spiritPower || 10, finalSpp),
            equipped: baseStats.equipped || { weapon: null, armor: null, head: null, boots: null, artifact: null, accessory: null },
            activeEffects: baseStats.activeEffects || []
        };
    }
    
    return {
        maxHp: expectedFinalHp, hp: expectedFinalHp,
        maxMp: expectedFinalMp, mp: expectedFinalMp,
        attack: finalAtk,
        defense: finalDef,
        speed: finalSpd,
        spiritPower: finalSpp,
        equipped: { weapon: null, armor: null, head: null, boots: null, artifact: null, accessory: null },
        activeEffects: []
    };
};

// V13.6: HỆ THỐNG TRẦN CHỈ SỐ (STAT CAP SYSTEM) CHO NPC
const applyNpcStatWithSaturation = (statName, prevVal, aiAbsoluteVal, isBonus = false, statKey, npc, forceBypass = false) => {
    if (aiAbsoluteVal === undefined || aiAbsoluteVal === null) return Number(prevVal) || 0;
    const targetVal = parseAIStat(aiAbsoluteVal);
    const baseValue = Number(prevVal) || (isBonus ? 0 : 10);
    const change = targetVal - baseValue;
    
    if (change <= 0) return targetVal;

    // 1. Ngoại Lệ Vĩ Mô, Đặc Quyền Admin, Chế Độ Ác Mộng & 10 Siêu Thực Thể Ngoại Hạn (Bỏ qua khóa trần hoàn toàn)
    const npcCleanName = String(npc?.name || '').toLowerCase();
    const isUncappedCosmicEntity = [
        'azathoth', 'phong đô đại đế', 'neoth', 'beyond anafabula', 'ma thần gurren lagann',
        'void demonbane', 'featherine', 'featherine augustus aurora', 'tự sự chí tôn', 'atroposx', 'bạch hoàng',
        'anos voldigoad', 'anos', 'ruphas mafahl', 'ruphas', 'bá hoàng nữ vương',
        'shallow vernal', 'bạch ngưng chi chủ', 'bất nghiệt tự điển',
        'orsted', 'long thần orsted', 'cổ trần sa', 'sailor galaxia', 'kha thần lục',
        'rimuru', 'rimuru tempest', 'rimura', 'hư vô thao thiết', 'vĩnh hằng cổ lĩnh chủ',
        'klein moretti', 'klein', 'ngu giả'
    ].some(n => npcCleanName.includes(n));

    if (forceBypass || isUncappedCosmicEntity || npc?.isNightmare) return baseValue + change;

    const currentStageConfig = getStageConfig(npc.level || 'Phàm Nhân');
    const hasTrait = (name) => npc.traits?.some(t => (t.name || t) === name);
    
    if (isBonus) {
        let finalLimit = 10 + (currentStageConfig.id * 5); 
        if (statKey === 'maxHp') finalLimit *= 20; 
        if (statKey === 'maxMp') finalLimit *= 10; 
        finalLimit *= 3; 
        
        if (statKey === 'maxHp' && hasTrait('Bàn Cổ Huyết Mạch')) finalLimit *= 5;

        if (change > finalLimit) {
            const excess = change - finalLimit;
            const absorbedExcess = Math.min(Math.floor(excess * 0.05), finalLimit * 2);
            const saturatedChange = finalLimit + absorbedExcess; 
            return baseValue + saturatedChange;
        }
        return baseValue + change;
    }

    let minorCapPct = 1.0;
    const lvlStr = String(npc.level || '').toLowerCase();
    if (lvlStr.includes('sơ kỳ')) minorCapPct = 0.30;
    else if (lvlStr.includes('trung kỳ')) minorCapPct = 0.55;
    else if (lvlStr.includes('hậu kỳ')) minorCapPct = 0.80;
    else if (lvlStr.includes('viên mãn')) minorCapPct = 1.0;
    else {
        const match = lvlStr.match(/tầng\s+(\d+)/);
        if (match) {
            const tang = parseInt(match[1]);
            minorCapPct = Math.min(1.0, Math.max(0.1, tang / 9));
        }
    }

    let HARD_CAP = 2625 * Math.pow(currentStageConfig.id, 3) * minorCapPct; 
    if (statKey === 'defense' && hasTrait('Bàn Cổ Huyết Mạch')) HARD_CAP *= 1.5;
    if (statKey === 'spiritPower' && hasTrait('Ngộ Tính Siêu Phàm')) HARD_CAP *= 1.5;
    if (statKey === 'speed' && hasTrait('Phong Ảnh Thể')) HARD_CAP *= 1.5;
    if (statKey === 'attack' && hasTrait('Tuyệt Thế Kiếm Tu')) HARD_CAP *= 1.2;

    const capRatio = baseValue / HARD_CAP;
    
    let effectiveChange = change;
    let multiplier = 1.0;
    if (capRatio >= 0.99) multiplier = 0.01;
    else if (capRatio >= 0.95) multiplier = 0.02;
    else if (capRatio >= 0.90) multiplier = 0.10;
    else if (capRatio >= 0.80) multiplier = 0.30;
    
    effectiveChange = change * multiplier;

    let maxChangePerTurn = Math.floor(15 * Math.pow(currentStageConfig.id, 1.8)) * 3;
    if (hasTrait('Thôn Kim Phệ Cốt Thể')) maxChangePerTurn *= 5;

    if (effectiveChange > maxChangePerTurn) {
        const excess = effectiveChange - maxChangePerTurn;
        const absorbedExcess = Math.min(Math.floor(excess * 0.05), maxChangePerTurn * 2);
        effectiveChange = maxChangePerTurn + absorbedExcess; 
    }
    
    return Math.floor(baseValue + effectiveChange);
};

// V10.94 & V2.55 FIX (HÀO VIP PRO): Hỗ trợ cả string và object traits cho NPC; bất tử tuyệt đối cho Đạo Tổ & Tiên Nhân
const calculateMaxAge = (level, traits = [], bgId = 'bg_0', bonusMaxAge = 0, race = 'Nhân tộc', currentAge = 0) => {
  const stageCfg = getStageConfig(level);
  let maxAge = stageCfg.baseMaxAge;
  const safeTraits = Array.isArray(traits) ? traits : [];
  const getTName = (t: any): string => (typeof t === 'string' ? t : (t?.name || ''));
  
  // V1.75: THỂ CHẤT THIÊN ĐỐ - Khóa trần thọ nguyên cơ bản 300 năm (chỉ tăng qua cắn đan diên thọ)
  if (hasThienDoTrait(safeTraits)) {
      maxAge = 300;
  }
  const raceStr = String(race).toLowerCase();
  
  // V1.22.4: BẢO TOÀN VÀ TĂNG THỌ CHO CÁC THẦN THỂ DUNG HỢP
  if (safeTraits.some(t => getTName(t) === 'Vạn Kiếp Chân Tôn Thể')) maxAge += 500000;
  if (safeTraits.some(t => getTName(t) === 'Tiên Thiên Bách Thảo Bất Tử Khu')) maxAge += 10000;
  if (safeTraits.some(t => (getTName(t) === 'Hỗn Độn Bàn Cổ Khu' || getTName(t) === 'Thập Nhị Đô Thiên Thần Sát Chân Thân'))) maxAge += 500;
  if (safeTraits.some(t => (getTName(t) === 'Hoang Cổ Chí Tôn Thể' || getTName(t) === 'Hỗn Độn Vạn Khí Cốt'))) maxAge += 200;
  if (safeTraits.some(t => getTName(t) === 'Đạo Tổ Toàn Tri Thể')) maxAge += 1000000;
  // V1.22.11b FIX: Thêm thọ nguyên cho 5 Thần Thể fusion thiếu
  if (safeTraits.some(t => getTName(t) === 'Bồ Đề Ma La Bất Hoại Thân')) maxAge += 9999999; // Bất hoại = gần bất tử
  if (safeTraits.some(t => (getTName(t) === 'Cơ Giới Hắc Quang Thể' || getTName(t) === 'Hạch Tâm Cơ Thần Khôi Lỗi' || getTName(t) === 'Chung Yên Điểm Kỳ Dị Thể'))) maxAge += 5000; // Cơ giới thể = bền bỉ
  if (safeTraits.some(t => getTName(t) === 'Vạn Trận Quy Tông Thể')) maxAge += 500; // Trận sư

  if (safeTraits.some(t => getTName(t) === 'Bàn Cổ Huyết Mạch')) maxAge += 50;
  if (safeTraits.some(t => getTName(t) === 'Trường Sinh Thể')) maxAge += 100;
  // V10.76 FIX: Đặc quyền thọ nguyên của Đạo Tổ hóa phàm
  if (safeTraits.some(t => getTName(t) === 'Đạo Tổ Niết Bàn')) maxAge += 100000; 
  if (safeTraits.some(t => getTName(t) === 'Trường Sinh Bất Lão')) maxAge += 9999999;
  if (safeTraits.some(t => getTName(t) === 'Tiên Phong Đạo Cốt')) maxAge += 10;
  if (safeTraits.some(t => getTName(t) === 'Đại Nạn Bất Tử')) maxAge += 20;
  if (safeTraits.some(t => getTName(t) === 'Tai Kiếp Liên Miên')) maxAge -= 20;
  if (safeTraits.some(t => getTName(t) === 'Ách Vận Bám Thân')) maxAge -= 15;
  // Dù có bị giảm nửa tuổi thọ, thì cộng với Vô Hạn vẫn là Vô Hạn
  if (safeTraits.some(t => getTName(t) === 'Thiên Đố Anh Tài')) maxAge = Math.floor(maxAge / 2);

  if (safeTraits.some(t => getTName(t) === 'Bán Tinh Linh (Huyết Mạch Lai)')) maxAge += 150;
  if (safeTraits.some(t => getTName(t) === 'Bán Long (Huyết Mạch Lai)')) maxAge += 300;
  if (safeTraits.some(t => getTName(t) === 'Bán Thần (Huyết Mạch Lai)')) maxAge += 500;
  if (safeTraits.some(t => (getTName(t) === 'Bán Yêu (Huyết Mạch Lai)' || getTName(t) === 'Bán Ma (Huyết Mạch Lai)' || getTName(t) === 'Bán Mị Ma (Huyết Mạch Lai)'))) maxAge += 50;

  // V10.94: Áp dụng Lớp Giáp Thứ 2 - Hệ Số Tuổi Thọ Chủng Tộc
if (/(rồng|long|thần|thái thản|titan)/.test(raceStr)) maxAge *= 100;
else if (/(cây|thảo mộc|thụ|linh sâm|mộc)/.test(raceStr)) maxAge *= 10;
else if (/(yêu|thú|cáo|sói|hổ|báo|hung|cự nhân)/.test(raceStr)) maxAge *= 5;

// Nhận diện kép (Đề phòng file bị mất ID xuất thân trong lúc tính toán)
const isPlant = bgId === 'bg_20' || safeTraits.some(t => getTName(t) === 'Bản Thể Thảo Mộc');
const isTreasure = bgId === 'bg_24' || safeTraits.some(t => getTName(t) === 'Thiên Tài Địa Bảo');
const isDemon = bgId === 'bg_25' || safeTraits.some(t => getTName(t) === 'Tiên Thiên Đại Yêu');
// V7.16 & V10.64 & V2.55 FIX: Bất tử cảnh giới (Chân Tiên ID >= 9 trở lên, Đạo Tổ, v.v.) và các dị loại Thạch Thần, Thi Tộc
const hasImmortalTrait = safeTraits.some(t => ['Thạch Thần Bất Diệt', 'Cơ Quan Hạch Tâm', 'Bảo Vật Hóa Hình', 'Trường Sinh Cửu Thị', 'Trường Sinh Bất Lão', 'Đạo Tổ Toàn Tri Thể'].includes(getTName(t)));
const isImmortal = stageCfg.id >= 9 || /(đạo tổ|tiên đế|tiên vương|tiên hoàng|tiên tôn|đại la|thái ất|kim tiên|huyền tiên|chân tiên|hư tiên|độ kiếp|đại thừa|chí tôn)/i.test(String(level || '')) || ['bg_21', 'bg_22', 'bg_23', 'bg_undead', 'bg_ctan'].includes(bgId) || hasImmortalTrait || /(đá|thạch|máy|khôi lỗi|kiếm|bảo vật|vong linh|cương thi)/.test(raceStr);

if (isPlant && maxAge < 500) maxAge += 500; 
if (isTreasure && maxAge < 1000) maxAge += 1000; 
if (isDemon && maxAge < 300) maxAge += 300; 

// V1.49: THỌ NGUYÊN YÊU TỘC THUẦN CHỦNG (Long tộc 200, Phượng hoàng 150 - Góp ý Ethan195)
if (bgId === 'bg_yeu_thuan_long') {
    if (stageCfg.id <= 2 && maxAge < 200) maxAge = 200;
    else maxAge += 100;
} else if (bgId === 'bg_yeu_thuan_phuong') {
    if (stageCfg.id <= 2 && maxAge < 150) maxAge = 150;
    else maxAge += 50;
} else if (['bg_yeu_thuan_mieu', 'bg_yeu_thuan_ho', 'bg_yeu_thuan_dieu', 'bg_yeu_thuan_di_toc', 'bg_yeu_thuan_ngu'].includes(bgId)) {
    if (stageCfg.id <= 2 && maxAge < 120) maxAge = 120;
    else maxAge += 20;
} 
if (isImmortal) maxAge += 9999999; // Bất tử tuyệt đối (10 triệu năm)

// V2.22 ETHAN195 FIX & V3.27 DARK FIX: Khóa sàn thọ nguyên bảo hiểm toàn diện
const effectiveBonus = Number(bonusMaxAge) || 0;
let finalMaxAge = maxAge + effectiveBonus;
// V3.27 FIX: Các bậc Bất Tử (Cấp 9+, Đạo Tổ, Vạn Ma Chi Chủ...) khóa cứng sàn thọ nguyên tối thiểu 10 triệu năm
if (isImmortal) {
    finalMaxAge = Math.max(10000000, finalMaxAge);
}
if (currentAge && Number(currentAge) > 0) {
    finalMaxAge = Math.max(Math.floor(Number(currentAge)) + 1, finalMaxAge);
}
return Math.max(10, finalMaxAge);
};

