// V3.28: Ánh xạ chuẩn vị diện theo stageId (1-20+)
export const getRealmTierByStageId = (stageId: number) => {
    if (stageId >= 20) return BASE_REALM_TIERS[3]; // Chí Cao Vị Diện
    if (stageId >= 18) return BASE_REALM_TIERS[2]; // Thượng Vị Diện
    if (stageId >= 11) return BASE_REALM_TIERS[1]; // Trung Vị Diện
    return BASE_REALM_TIERS[0]; // Hạ Vị Diện
};

// V3.28 (LỆNH TOÀ ÁN TỐI CAO - THÀNH KHÔN & DARK): TỰ ĐỘNG PHÂN LOẠI ĐẲNG CẤP VI DIỆN & CÕI DLC
