  useEffect(() => {
      let isPushingError = false; // V13.6 FIX: Cờ chống đệ quy (Infinite Loop)

      const pushDetailedError = (errorMsg, errorStack, eventSource = '', lineno = '', colno = '') => {
          if (isPushingError) return; // Chặn nếu đang push
          try {
              // Lưới lọc cực mạnh: Bỏ qua lỗi Firebase để chống đệ quy (Write stream exhausted)
              if (String(errorMsg).includes('firebase') || String(errorMsg).includes('Firestore') || String(errorMsg).includes('Write stream') || String(errorStack).includes('firebase')) return;

              isPushingError = true;
              const state = gameStateRef.current || {};
              const logs = storyLogRef.current || [];
              const currentUser = userRef.current;
              
              if (currentUser && currentUser.uid) {
                  const detailedLog = {
                      time: new Date().toLocaleString('vi-VN'),
                      errorMsg: errorMsg,
                      errorStack: errorStack,
                      action: state.recentBehavior || 'Không rõ',
                      traits: (state.traits || []).map(t => t.name).join(', ') || 'Không có',
                      inventory: (state.inventory || []).map(i => `${i.name} (x${i.quantity})`).join(', ') || 'Trống',
                      recentStory: logs.slice(-5).map(l => l.text).join('\n') || 'Không có'
                  };
                  addDoc(collection(db, 'artifacts', appId, 'public', 'data', 'admin_global_logs'), {
                      type: 'error_report',
                      detail: JSON.stringify(detailedLog),
                      name: state.name || 'Vô danh',
                      uid: currentUser.uid,
                      level: state.cultivationLevel || 'Phàm nhân',
                      timestamp: Date.now()
                  }).finally(() => {
                      isPushingError = false; // Mở khóa sau khi push xong
                  });
              } else {
                  isPushingError = false;
              }
          } catch(e) {
              isPushingError = false;
          }
      };

      const handleError = (event) => {
          const newLog = {
              time: new Date().toLocaleString('vi-VN'),
              message: event.message || 'Lỗi không xác định',
              source: event.filename || '',
              lineno: event.lineno || '',
              colno: event.colno || '',
              errorObj: event.error ? (event.error.stack || event.error.toString()) : ''
          };
          setErrorLogs(prev => [newLog, ...prev].slice(0, 100));
          pushDetailedError(event.message || 'Lỗi không xác định', event.error ? (event.error.stack || event.error.toString()) : '', event.filename, event.lineno, event.colno);
      };

      const handleUnhandledRejection = (event) => {
          const newLog = {
              time: new Date().toLocaleString('vi-VN'),
              message: event.reason ? (event.reason.message || event.reason.toString()) : 'Unhandled Promise Rejection',
              source: 'Promise',
              lineno: '',
              colno: '',
              errorObj: event.reason ? (event.reason.stack || '') : ''
          };
          setErrorLogs(prev => [newLog, ...prev].slice(0, 100));
          pushDetailedError(event.reason ? (event.reason.message || event.reason.toString()) : 'Unhandled Promise Rejection', event.reason ? (event.reason.stack || '') : '');
      };

      window.addEventListener('error', handleError);
      window.addEventListener('unhandledrejection', handleUnhandledRejection);

      const originalConsoleError = console.error;
      console.error = (...args) => {
          const errorMsg = args.map(a => (typeof a === 'object' && a !== null) ? (a.stack || JSON.stringify(a)) : String(a)).join(' ');
          
          // CHẶN INFINITE LOOP: Bỏ qua các lỗi của chính Firebase để không đẻ ra đệ quy làm cháy Write Stream
          if (errorMsg.includes('firebase') || errorMsg.includes('Firestore') || errorMsg.includes('Write stream') || errorMsg.includes('backoff delay') || errorMsg.includes('resource-exhausted')) {
              originalConsoleError.apply(console, args);
              return;
          }

          const newLog = {
              time: new Date().toLocaleString('vi-VN'),
              message: 'Console Error',
              source: '',
              lineno: '',
              colno: '',
              errorObj: errorMsg
          };
          setErrorLogs(prev => [newLog, ...prev].slice(0, 100));
          pushDetailedError('Console Error', errorMsg);
          originalConsoleError.apply(console, args);
      };

      return () => {
          window.removeEventListener('error', handleError);
          window.removeEventListener('unhandledrejection', handleUnhandledRejection);
          console.error = originalConsoleError;
      };
  }, []);

