          responseText = responseText.replace(/```json_admin_fix\s*[\s\S]*?```/gi, '').replace(/```\s*(\{[\s\S]*?"fixApplied"[\s\S]*?\})\s*```/gi, '').trim();
          
          setPlayerAiChatMessages(prev => [...prev, { role: 'ai', text: responseText }]);
