      const genZCom = getVal('settingGenZCombat', 'tuTienGenZCombat');
      if (genZCom !== undefined && genZCom !== null) {
        const val = String(genZCom) === 'true';
        setSettingGenZCombat(val);
        localStorage.setItem('tuTienGenZCombat', String(val));
      }
      const genZCu = getVal('settingGenZCultivate', 'tuTienGenZCultivate');
      if (genZCu !== undefined && genZCu !== null) {
        const val = String(genZCu) === 'true';
        setSettingGenZCultivate(val);
        localStorage.setItem('tuTienGenZCultivate', String(val));
      }
      const subStats = getVal('visibleSubStats', 'tuTienSubStats');
      if (subStats !== undefined && subStats !== null) {
        try {
          const arr = Array.isArray(subStats) ? subStats : JSON.parse(subStats);
          if (Array.isArray(arr)) {
            setVisibleSubStats(arr);
            localStorage.setItem('tuTienSubStats', JSON.stringify(arr));
          }
        } catch(e) {}
      }
      const logAnti = getVal('logFilterAntiCheat', 'tuTienLogAntiCheat');
      if (logAnti !== undefined && logAnti !== null) {
        const val = String(logAnti) !== 'false';
        setLogFilterAntiCheat(val);
        localStorage.setItem('tuTienLogAntiCheat', String(val));
      }
      const logSt = getVal('logFilterStats', 'tuTienLogStats');
