  // V7.87 & V12.42: Thuật toán nhận diện và khóa chéo Khí vận (Mutually Exclusive)
  const lockedTraitIds = useMemo(() => {
      let locked = new Set();
      let hasNormalTrait = false;
      let hasSystemTrait = false;

      selectedTraitIds.forEach(id => {
          const trait = TRAITS_POOL.find(t => t.id === id);
          if (trait) {
              if (Array.isArray(trait.incompatible)) {
                  trait.incompatible.forEach(incId => locked.add(incId));
              }
              if (trait.isSystemParent || trait.isSystemChild) {
                  hasSystemTrait = true;
              } else {
                  hasNormalTrait = true;
              }
          }
      });

      // V1.88 (Báo lỗi Hunggth8): Chỉ khóa các Hệ Thống khác nếu đã chọn 1 Hệ Thống (duy nhất 1 Hệ Thống mỗi kiếp), cho phép chọn tự do các khí vận thường song hành.
      if (hasSystemTrait) {
          TRAITS_POOL.filter(t => (t.isSystemParent || t.isSystemChild) && !selectedTraitIds.includes(t.id)).forEach(t => locked.add(t.id));
      }
      // V1.49: KHÓA CHẶT KHÍ VẬN CẤM KỴ CỦA YÊU TỘC THUẦN CHỦNG (Góp ý Ethan195)
      // V1.79: KHÓA CHẶT KHÍ VẬN CỦA THIÊN ĐẠO KHƯỚC TỪ (Góp ý Kha)
      if (typeof selectedBgId !== 'undefined' && selectedBgId === 'bg_thien_dao_khuoc_tu') {
          TRAITS_POOL.forEach(t => {
              const n = (t.name || '').toLowerCase();
              const d = (t.desc || '').toLowerCase();
              if (
                  t.isSystemParent || t.isSystemChild ||
                  n.includes('thiên mệnh') || n.includes('khí vận chi tử') || n.includes('khí vận chi nữ') ||
                  n.includes('may mắn') || n.includes('phúc duyên') || n.includes('hệ thống') ||
                  n.includes('quý nhân') || n.includes('hồng vận') || n.includes('đại vận') ||
                  d.includes('thiên đạo gia hộ') || d.includes('may mắn') || d.includes('quý nhân phù trợ') ||
                  [201, 202, 203, 2002, 901, 902, 903, 904, 905].includes(t.id)
              ) {
                  locked.add(t.id);
              }
          });
      }

      if (typeof selectedBgId !== 'undefined' && isPureYeuTocBg(selectedBgId)) {
          locked.add(504); // Kẻ Ăn Mày
          locked.add(605); // Thái Cổ Ngự Yêu Sư
          locked.add(803); // Vạn Thú Thân Hòa
          TRAITS_POOL.filter(t => t.isSystemParent || t.isSystemChild).forEach(t => locked.add(t.id)); // Hệ Thống Gia Hộ
      }

      return Array.from(locked);
  }, [selectedTraitIds, selectedBgId]);

