      universe: rawGameState.universe || 'tutien', // V12.17: Khôi phục ADN Vũ Trụ
      customAppearance: rawGameState.customAppearance || '', // V11.76 Khôi phục ngoại hình
      customPersonality: rawGameState.customPersonality || '', // V2.0: Khôi phục tính cách tự do
      cultivationLevel: cleanCultivationLevel, 
