                const regex = new RegExp(escapeRegexHelper(deadName) + "(?!\\s*\\(ĐÃ CHẾT\\))", 'gi');
                sanitizedRecentStory = sanitizedRecentStory.replace(regex, `${deadName} (ĐÃ CHẾT - THẦN TIÊU XÁC TÁN)`);
                sanitizedCoreMemory = sanitizedCoreMemory.replace(regex, `${deadName} (ĐÃ CHẾT - THẦN TIÊU XÁC TÁN)`);
