    // 1. Quét sạch những kẻ đã chết, không cho chui vào não AI gây ảo giác
    const isSummoningDead = /(chiêu hồn|gọi hồn|nghĩa trang|mộ|xác|chết|người chết|vong linh)/.test(sanitizedActionText.toLowerCase());
