        cinematicPrompt += `LỆNH THÉP V12.43 (BẢO HỘ TÂN THỦ): ĐÂY LÀ CHƯƠNG ĐẦU TIÊN VỪA MỚI VÀO GAME. BẠN BỊ CẤM TUYỆT ĐỐI VIỆC LÀM CHO NVC CHẾT HOẶC MẤT MÁU QUÁ NẶNG! Bất chấp xuất thân có thê thảm đến đâu, hãy mở ra một tia hi vọng sinh cơ!\n`;
        
        // V11.44 FIX: Khai báo lại các biến Thiên Hướng bên trong scope của callGeminiAPI để tránh lỗi ReferenceError
        const isTanker = activeState.defense >= 25 || (activeState.traits || []).some(t => /(Bàn Cổ|Cự Nhân|Thiết Cốt|Thạch Thần)/.test(t.name));
        const isMage = activeState.spiritPower >= 25 || (activeState.traits || []).some(t => /(Phật Cốt|Huyễn Mộng|Ngộ Tính|Trận Tổ)/.test(t.name));
        const isAssassin = activeState.speed >= 25 || (activeState.traits || []).some(t => /(Phong Ảnh|Thuấn Di|Tuyệt Dục|Hư Không)/.test(t.name));
        const isTrash = activeState.talent <= 5 && activeState.enlightenment <= 5;

        const forceAggressiveBg = ['bg_linh_quen', 'bg_tu_tu', 'bg_no_le', 'dau_khi'];
        const isPeacefulStart = isNativeOrigin ? true : (!forceAggressiveBg.includes(activeState.backgroundId) && (Math.random() < 0.5));

