                      // 2. Virus Khoa Kỹ (Blacklight / Technocyte / Singularity)
                      const hasBlacklight = activeState.traits?.some(t => t.name.includes('Hắc Quang Bệnh Độc') || t.name.includes('Cơ Giới Hắc Quang Thể') || t.name.includes('Dịch Bệnh Điểm Kỳ Dị'));
                      const hasTechnocyte = activeState.traits?.some(t => t.name.includes('Cơ Giới Bệnh Độc') || t.name.includes('Cơ Giới Hắc Quang Thể') || t.name.includes('Dịch Bệnh Điểm Kỳ Dị'));
                      const hasOmniVirus = activeState.traits?.some(t => t.name.includes('Cơ Giới Hắc Quang Thể') || t.name.includes('Dịch Bệnh Điểm Kỳ Dị'));
                      
