                          const isUsingItems = /(uống|nuốt|cắn|dùng|đan|dược|pháp bảo|thần khí|trang bị|tạo hóa)/.test(actionStr);
                          const isRebelling = /(nghịch thiên|đoạt quyền|chém thiên đạo|thay trời đổi đất|đạp nát|giẫm đạp|cướp quyền|nghiền nát)/.test(actionStr);
