                              let survivalRate = 0.1 + (prev.enlightenment / 1000) + (prev.karma >= 50 ? 0.2 : 0) + (prev.traits.some(t => t.name === 'Đại Khí Vận' || t.name === 'Thiên Mệnh Chi Tử' || t.name === 'Khí Vận Chi Tử' || t.name === 'Khí Vận Chi Nữ' || t.name === 'Thiên Mệnh Ma Tôn' || t.id === 2088) ? 0.3 : 0);
                              
